<?php require_once __DIR__.'/../includes/layout.php'; require_once __DIR__.'/../includes/user.php'; $u=require_login(); $s=db()->prepare('SELECT u.*,p.*,m.name madrasa,po.name position,r.name role_name FROM users u LEFT JOIN user_profiles p ON p.user_id=u.id LEFT JOIN madrasas m ON m.id=u.madrasa_id LEFT JOIN positions po ON po.id=u.position_id JOIN roles r ON r.id=u.role_id WHERE u.id=?'); $s->execute([$u['id']]); $p=$s->fetch(); dashboard_header('My Profile'); ?><div class="row g-4"><div class="col-lg-4"><div class="glass-card p-4 text-center hover-glow"><img class="avatar" src="<?=APP_BASE?>/<?=e($p['photo'] ?: 'assets/img/avatar.svg')?>" alt="Profile photo"><h3 class="mt-3"><?=e($p['full_name'])?></h3><p><?=e($p['role_name'])?> · <?=e($p['position'])?></p><div class="progress"><div class="progress-bar" style="width:<?=profile_completion($p)?>%"></div></div><small>Profile completion <?=profile_completion($p)?>%</small></div></div><div class="col-lg-8"><div class="glass-card p-4"><h4>Full Information</h4><div class="row"><?php foreach(['email','username','address','place','district','state','country','living_place','working_place','certificate_number','msr_number','phone','madrasa','last_login'] as $f):?><div class="col-md-6 mb-3"><small class="text-muted"><?=ucwords(str_replace('_',' ',$f))?></small><div class="fw-bold"><?=e($p[$f]??'—')?></div></div><?php endforeach;?></div><a class="btn btn-premium" href="account-settings.php">Edit Profile</a> <a class="btn btn-outline-primary rounded-pill" href="change-password.php">Change Password</a><button class="btn btn-outline-secondary rounded-pill" onclick="window.print()">Download</button></div></div></div><?php dashboard_footer(); ?>
